package br.com.axecloud.app.feature.foundations
import androidx.lifecycle.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject
@HiltViewModel class FoundationViewModel @Inject constructor(private val repo:FoundationRepository):ViewModel(){private val m=MutableStateFlow(FoundationUiState());val state=m.asStateFlow();init{load()};fun load()=viewModelScope.launch{m.update{it.copy(loading=true,error=null)};runCatching{repo.load()}.onSuccess{p->m.update{it.copy(loading=false,manager=p.manager,items=p.items,children=p.children,houseTradition=p.tradition)}}.onFailure{e->m.update{it.copy(loading=false,error=e.message)}}};fun query(v:String)=m.update{it.copy(query=v)};fun category(v:String)=m.update{it.copy(category=v)};fun editor(v:Foundation?=null,open:Boolean=true)=m.update{it.copy(editor=v,editorOpen=open,error=null)};fun select(v:Foundation?) {if(v==null)m.update{it.copy(selected=null)}else viewModelScope.launch{m.update{it.copy(actionId=v.id,error=null)};runCatching{repo.detail(v.id)}.onSuccess{x->m.update{it.copy(actionId=null,selected=x)}}.onFailure{e->m.update{it.copy(actionId=null,error=e.message)}}}};fun consume()=m.update{it.copy(message=null)};fun save(v:FoundationForm)=viewModelScope.launch{m.update{it.copy(saving=true,error=null)};runCatching{repo.save(v,m.value.editor?.id);repo.load()}.onSuccess{p->m.update{it.copy(saving=false,editorOpen=false,items=p.items,message=if(v.status=="publicado")"Fundamento liberado com acesso controlado." else "Rascunho salvo.")}}.onFailure{e->m.update{it.copy(saving=false,error=e.message)}}}}
